<span class="line"><span style="color:#ABB2BF;">        node, dist </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> queue.</span><span style="color:#61AFEF;">popleft</span><span style="color:#ABB2BF;">()</span></span>
