<span class="line"><span style="color:#C678DD;">            if</span><span style="color:#ABB2BF;"> neighbor </span><span style="color:#C678DD;">not</span><span style="color:#C678DD;"> in</span><span style="color:#ABB2BF;"> visited:</span></span>
